import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { accordionLabelCSS } from './Accordion.sty.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { Text } from '../../typography/Text.js';

export type AccordionSectionLabelProps = WithChildren &
  StylingProps &
  DataTestId;

/** Accordion Section Label component */
export const AccordionSectionLabel = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  AccordionSectionLabelProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: AccordionSectionLabelProps = props;
  const childIsText = _isStringChildren(children);

  return (
    <div
      data-testid={dataTestId}
      ref={forwardedRef}
      className={clsx(accordionLabelCSS, consumerClassName)}
      style={consumerStyle}
    >
      {childIsText ? (
        <Text textStyle="base-emphasized" as="p">
          {children}
        </Text>
      ) : (
        children
      )}
    </div>
  );
});

(
  AccordionSectionLabel as typeof AccordionSectionLabel & {
    displayName: string;
  }
).displayName = 'Accordion.SectionLabel';
